    guy_hand_patches = image_patch.find("hand")
    guy_face_patches = image_patch.find("face")

    if not guy_hand_patches or not guy_face_patches:
        return target_person

    hands_closest_to_target = sorted(guy_hand_patches, key=lambda h: distance(target_person, h))
    faces_closest_to_target = sorted(guy_face_patches, key=lambda f: distance(target_person, f))

