def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    gal_patches = image_patch.find("gal")
    person_patches = image_patch.find("person")

    if not gal_patches:
        return image_patch

    if not person_patches:
        return gal_patches[0]

    gal_centers = [(p.left + p.right) / 2 for p in gal_patches]
    person_centers = [(p.left + p.right) / 2 for p in person_patches]

    min_distance = float('inf')
    best_match = None

    for gal_center in gal_centers:
        for person_center in person_centers:
            dist = abs(gal_center - person_center)
            if dist < min_distance:
                min_distance = dist
                best_match = person_patches[person_centers.index(person_center)]

    return best_match

