def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    guy_patches = image_patch.find("guy")
    cow_patches = image_patch.find("cow")

    if not guy_patches or not cow_patches:
        return image_patch

    min_distance = float('inf')
    best_guy = None

    for guy in guy_patches:
        for cow in cow_patches:
            d = distance(guy, cow)
            if d < min_distance:
                min_distance = d
                best_guy = guy

    return best_guy

