def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    women = image_patch.find("woman")
    children = image_patch.find("child")

    if not women or not children:
        return image_patch

    washed_children = []
    for woman in women:
        for child in children:
            if woman.overlaps_with(child.left, child.lower, child.right, child.upper):
                washed_children.append(child)

    if not washed_children:
        return image_patch

    washed_children.sort(key=lambda c: c.horizontal_center)
    return washed_children[0]

